from pathlib import Path
from html import escape
import json
import re
r=Path(__file__).resolve().parents[1]
base='https://mikkelwintherpedersen.dk/'
cv='downloads/CV-Mikkel-Winther-Pedersen-Nov2026.pdf'
profile='https://researchprofiles.ku.dk/en/persons/mikkel-winther-pedersen/'
bio='Mikkel Winther Pedersen is an Associate Professor at the Globe Institute, University of Copenhagen, where he leads the Palaeo-Environmental Genomics Group. He studies DNA preserved in soil and sediments to reconstruct past ecosystems and understand how climate and human activities have shaped biodiversity. His work combines geography, genetics and bioinformatics, with field research spanning the Arctic and beyond. He contributed to the discovery of a two-million-year-old ecosystem in Greenland using environmental DNA.'
(r/'downloads/Mikkel-Winther-Pedersen-short-biography.txt').write_text('Mikkel Winther Pedersen — short biography\n\n'+bio+'\n\nContact: mwpedersen@sund.ku.dk\nUniversity of Copenhagen, Globe Institute\nUpdated November 2026\n',encoding='utf-8')
translations = json.loads((r/'scripts/da.json').read_text(encoding='utf-8'))
bio_da = 'Mikkel Winther Pedersen er lektor på Globe Institute ved Københavns Universitet, hvor han leder Palaeo-Environmental Genomics Group. Han undersøger DNA bevaret i jord og sedimenter for at rekonstruere fortidens økosystemer og forstå, hvordan klima og menneskers aktiviteter har påvirket biodiversiteten. Hans arbejde kombinerer geografi, genetik og bioinformatik med feltarbejde i Arktis og andre dele af verden. Han har bidraget til opdagelsen af et to millioner år gammelt økosystem i Grønland ved hjælp af miljø-DNA.'
translations[bio] = bio_da
# Match full paragraphs before shorter labels, while retaining official names.
# Protecting names with placeholders first would prevent paragraph matches.
for name in ('Palaeo-Environmental Genomics Group', 'Palaeo-Environmental<br>Genomics Group'):
 translations[name] = name
for source, target in list(translations.items()):
 translations.setdefault(escape(source, quote=True), escape(target, quote=True))
pattern = re.compile('|'.join(re.escape(key) for key in sorted(translations, key=len, reverse=True)))
def translate(text):
 return pattern.sub(lambda match: translations[match.group()], text)
(r/'downloads/Mikkel-Winther-Pedersen-kort-biografi.txt').write_text('Mikkel Winther Pedersen — kort biografi\n\n'+bio_da+'\n\nKontakt: mwpedersen@sund.ku.dk\nKøbenhavns Universitet, Globe Institute\nOpdateret november 2026\n', encoding='utf-8')
seo = json.loads((r/'seo.json').read_text(encoding='utf-8'))
def page(file,title,desc,body):
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if file==url else '')+f'>{label}</a>' for url,label in [('index.html','Home'),('about.html','About & CV'),('group.html','Group'),('talks.html','Talks'),('press.html','For journalists')])
 content=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Mikkel Winther Pedersen</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="theme-color" content="#216454"><link rel="canonical" href="{base+('' if file=='index.html' else file)}"><meta property="og:title" content="{escape(title,quote=True)} | Mikkel Winther Pedersen"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{base+file}"><meta property="og:image" content="{base}assets/mikkel-portrait.jpg"><link rel="stylesheet" href="assets/style.css"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html">Mikkel Winther Pedersen<small>Ancient environmental genomics</small></a><nav class="nav" aria-label="Main navigation">{nav}</nav></div></header><main id="main">{body}</main><footer class="site-footer"><div class="wrap footer-inner"><span>Mikkel Winther Pedersen · University of Copenhagen</span><div class="footer-links"><a href="https://www.linkedin.com/in/mikkel-winther-pedersen/">LinkedIn</a><a href="https://orcid.org/0000-0002-7291-8887">ORCID</a><a href="https://github.com/miwipe">GitHub</a><a href="mailto:mwpedersen@sund.ku.dk">Email</a></div></div></footer></body></html>'''
 for lang in ('da','en'):
  output = content
  if lang == 'da':
   output = translate(output)
   output = output.replace('<html lang="en">', '<html lang="da">')
   output = output.replace('downloads/Mikkel-Winther-Pedersen-short-biography.txt', 'downloads/Mikkel-Winther-Pedersen-kort-biografi.txt')
  else:
   output = re.sub(r'(href|src)="(assets/|downloads/)', r'\1="../\2', output)
   output = output.replace(f'href="{base}', f'href="{base}en/')
   output = output.replace(f'content="{base+file}"', f'content="{base}en/{file}"')
  danish_url = base + ('' if file == 'index.html' else file)
  english_url = base + 'en/' + ('' if file == 'index.html' else file)
  page_url = danish_url if lang == 'da' else english_url
  metadata = seo[file][lang]
  output = re.sub(r'<title>.*?</title>', lambda _: '<title>'+escape(metadata['title'])+'</title>', output)
  for attr, key, value in [('name', 'description', metadata['description']), ('property', 'og:title', metadata['title']), ('property', 'og:description', metadata['description']), ('property', 'og:url', page_url)]:
   output = re.sub(r'<meta '+attr+'="'+re.escape(key)+r'" content="[^"]*">', lambda _, attr=attr, key=key, value=value: f'<meta {attr}="{key}" content="{escape(value, quote=True)}">', output)
  person_id = base+'#person'
  person = {
   '@type': 'Person', '@id': person_id, 'name': 'Mikkel Winther Pedersen',
   'url': base, 'image': base+'assets/mikkel-portrait.jpg',
   'jobTitle': 'Lektor' if lang == 'da' else 'Associate Professor',
   'worksFor': {'@type': 'Organization', 'name': 'Københavns Universitet' if lang == 'da' else 'University of Copenhagen', 'url': 'https://www.ku.dk/'},
   'sameAs': [profile, 'https://www.linkedin.com/in/mikkel-winther-pedersen/', 'https://orcid.org/0000-0002-7291-8887', 'https://github.com/miwipe']
  }
  webpage = {'@type': 'ProfilePage' if file == 'about.html' else 'WebPage', '@id': page_url+'#webpage', 'url': page_url, 'name': metadata['title'], 'description': metadata['description'], 'inLanguage': lang, 'about': {'@id': person_id}}
  if file == 'about.html': webpage['mainEntity'] = {'@id': person_id}
  structured = json.dumps({'@context': 'https://schema.org', '@graph': [person, webpage]}, ensure_ascii=False).replace('<', chr(92)+'u003c')
  output = output.replace('</head>', '<script type="application/ld+json">'+structured+'</script></head>')
  alternates = f'<link rel="alternate" hreflang="da" href="{danish_url}"><link rel="alternate" hreflang="en" href="{english_url}"><link rel="alternate" hreflang="x-default" href="{danish_url}">'
  output = output.replace('</head>', alternates+'</head>')
  da_link = file if lang == 'da' else '../'+file
  en_link = 'en/'+file if lang == 'da' else file
  language_nav = '<nav class="languages" aria-label="'+('Sprog' if lang == 'da' else 'Language')+'">'
  language_nav += f'<a href="{da_link}" lang="da" hreflang="da"'+(' aria-current="true"' if lang == 'da' else '')+'>Dansk</a>'
  language_nav += f'<a href="{en_link}" lang="en" hreflang="en"'+(' aria-current="true"' if lang == 'en' else '')+'>English</a></nav>'
  output = output.replace('</nav></div></header>', '</nav>'+language_nav+'</div></header>')
  dest = r if lang == 'da' else r/'en'
  dest.mkdir(exist_ok=True)
  (dest/file).write_text(output, encoding='utf-8')
papers=[('2026', 'From bones to sediments: Ancient human DNA from open-air archaeological sites', 'Sawafuji et al. · Journal of Archaeological Science', '10.1016/j.jas.2026.106537', 'Human DNA recovered from sediments at an open-air burial site in Japan expands the possibilities for studying past populations.'), ('2025', 'Continuous mitochondrial diversity of Danube sturgeon species over millennia: insights from ancient DNA', 'Zampirolo et al. · Philosophical Transactions B', '10.1098/rstb.2024.0034', 'Ancient DNA from sturgeon remains traces genetic diversity in the Danube over millennia, providing a historical perspective for conservation.'), ('2024', 'Tracing early pastoralism in Central Europe using sedimentary ancient DNA', 'Zampirolo et al. · Current Biology', '10.1016/j.cub.2024.08.047', 'DNA in sediments reveals traces of domestic animals and sheds light on the history of herding and forest use in Central Europe.'), ('2022', 'A 2-million-year-old ecosystem in Greenland uncovered by environmental DNA', 'Kjær, Pedersen, De Sanctis et al. · Nature', '10.1038/s41586-022-05453-y', 'Two-million-year-old DNA reveals a lost ecosystem of plants and animals in a much warmer northern Greenland.'), ('2021', 'Late Quaternary dynamics of Arctic biota from ancient environmental genomics', 'Wang, Pedersen, Alsos et al. · Nature', '10.1038/s41586-021-04016-x', 'DNA from Arctic sediments reconstructs changes in plant and mammal communities over the past 50,000 years.'), ('2016', 'Postglacial viability and colonization in North America’s ice-free corridor', 'Pedersen et al. · Nature', '10.1038/nature19085', 'Ancient DNA helps establish when the ice-free corridor could support people, shedding light on early migration routes into the Americas.')]
paperhtml=''.join(f'<article class="paper"><span class="year">{y}</span><div><h3><a href="https://doi.org/{doi}">{escape(t)}</a></h3><p>{escape(a)}</p><p class="paper-summary">{escape(summary)}</p></div></article>' for y,t,a,doi,summary in papers)
page('index.html','Home','Exploring past ecosystems through ancient DNA. Research, publications and the Palaeo-Environmental Genomics Group at the University of Copenhagen.',f'''<div class="wrap"><section class="hero" aria-labelledby="intro"><div><p class="eyebrow">Geography · Genetics · Past ecosystems</p><h1 id="intro">Reading the past<br>through ancient DNA.</h1><p class="lead">I’m Mikkel Winther Pedersen, a geneticist, geographer and speaker studying the traces of life preserved in soil and sediments.</p><p>My research explores how ecosystems, climate and human activities have changed through time.</p><div class="buttons"><a class="button" href="#research">Explore the research</a><a class="button secondary" href="{cv}">Download CV</a><a class="button secondary" href="talks.html">Talks and enquiries</a></div></div><figure><img src="assets/mikkel-portrait.jpg" alt="Mikkel Winther Pedersen, wearing glasses and a checked shirt" width="1000" height="1250" fetchpriority="high"><figcaption class="caption">Portrait: Nicolai West</figcaption></figure></section><div class="affiliation"><span>Associate Professor · Globe Institute</span><span>Palaeo-Environmental Genomics Group · University of Copenhagen</span></div><section class="section" id="research"><div class="section-heading"><h2>Traces of life.<br>Histories of change.</h2><p>From sediment samples to genomic data, I work across field research and computational biology to investigate the living world of the past.</p></div><div class="research-grid"><article><h3>Past ecosystems</h3><p>Recovering ancient environmental DNA to investigate past communities of plants and animals, from Arctic landscapes to lake sediments.</p></article><article><h3>People & environments</h3><p>Exploring the relationships between human activity, biodiversity and environmental change in archaeological and natural archives.</p></article><article><h3>Methods & open science</h3><p>Developing computational approaches for analysing ancient metagenomic data and sharing tools that support reproducible research.</p><p><a href="https://github.com/miwipe">Research code on GitHub</a></p></article></div></section></div><section class="tinted"><div class="wrap section"><div class="section-heading"><h2>Selected research</h2><a href="{profile}">Full publication record</a></div>{paperhtml}</div></section><div class="wrap"><section class="contact-band"><div><p class="eyebrow">Palaeo-Environmental Genomics Group</p><h2>Research is a shared effort.</h2><p>Meet the people in my group.</p></div><a class="button secondary" href="group.html">Meet the group</a></section></div>''')
page('about.html','About & CV','Research background, academic career and the November 2026 CV of Mikkel Winther Pedersen.',f'''<div class="wrap"><div class="page-intro"><p class="eyebrow">About & curriculum vitae</p><h1>A geographer’s perspective.<br>A geneticist’s tools.</h1><p class="lead">I study the history of nature through DNA left behind in the environment.</p></div><div class="two-col"><div class="prose"><h2>Research & background</h2><p>I am an Associate Professor at the Globe Institute, University of Copenhagen, and lead the Palaeo-Environmental Genomics Group. My work brings together geography, genetics and bioinformatics to reconstruct past ecosystems and explore their responses to climate and human activity.</p><p>My research has contributed to the discovery of a two-million-year-old ecosystem in Greenland and to studies of Arctic biodiversity, early pastoralism and the environments encountered by early human populations.</p><p>Fieldwork is an important part of this research. I have led expeditions in Alaska, the United States, Morocco, Canada, northern Sweden and the Republic of the Congo, alongside work with colleagues across the Arctic and beyond.</p><h2>Teaching & collaboration</h2><p>I teach the PhD course Ancient Environmental Genomics and supervise students and researchers working across field, laboratory and computational approaches. I am a co-PI in the <a href="https://aegisearth.bio/en">Ancient Environmental Genomics Initiative for Sustainability (AEGIS)</a> and the <a href="https://globe.ku.dk/research/caeg/">Centre for Ancient Environmental Genomics</a>.</p><h2>Academic path</h2><ul class="timeline"><li><span>September 2026–present · University of Copenhagen</span>Associate Professor, Globe Institute</li><li><span>2019–2026 · University of Copenhagen</span>Assistant Professor; tenure track from 2022</li><li><span>2017–2019 · University of Cambridge</span>Carlsberg Foundation Postdoctoral Researcher</li><li><span>2016 · University of Copenhagen</span>PhD in Palaeogenetics</li><li><span>2011 · University of Copenhagen</span>MSc in Geography and Geoinformatics</li></ul></div><aside class="aside"><h2>Curriculum vitae</h2><p>Academic positions, education, research leadership, selected funding and publications.</p><p class="note">Updated November 2026 · PDF</p><div class="buttons"><a class="button" href="{cv}" download>Download CV</a><a class="button secondary" href="https://www.linkedin.com/in/mikkel-winther-pedersen/">My LinkedIn profile</a></div><h2 style="margin-top:32px">Get in touch</h2><p><a href="mailto:mwpedersen@sund.ku.dk">mwpedersen@sund.ku.dk</a></p><p>Globe Institute<br>University of Copenhagen<br>Øster Voldgade 5–7<br>1350 Copenhagen K, Denmark</p><p><a href="{profile}">University research profile</a></p><p><a href="press.html">Information for journalists</a></p></aside></div></div>''')
peoplepath=r/'people.json'
people=json.loads(peoplepath.read_text())
cards=''
for p in people:
 name=escape(p['name']); initials=''.join(w[0] for w in p['name'].split()[:2])
 pic=f'<img src="{p["image"]}" alt="{name}" width="480" height="600" loading="lazy">' if p['image'] else f'<div class="initials" aria-label="Portrait forthcoming">{initials}</div>'
 cards+=f'<article class="person">{pic}<h2>{name}</h2><p class="role">{escape(p["role"])}</p>'+(f'<p>{escape(p["bio"])}</p>' if p['bio'] else '')+(f'<a class="profile" href="{p["profile"]}">{escape(p.get("profile_label", "LinkedIn"))}</a>' if p['profile'] else '')+'</article>'
page('group.html','The group','Meet the Palaeo-Environmental Genomics Group at the Globe Institute, University of Copenhagen.',f'''<div class="wrap"><div class="page-intro"><p class="eyebrow">People & collaboration</p><h1>Palaeo-Environmental<br>Genomics Group</h1><p class="lead">We investigate past ecosystems through ancient environmental DNA, bringing together expertise in field research, laboratory analysis and computational biology.</p><p>Led by <a href="about.html">Mikkel Winther Pedersen</a> at the Globe Institute, University of Copenhagen.</p></div><section class="people" aria-label="Group members">{cards}</section></div><div class="tinted"><div class="wrap contact-band"><div><h2>Interested in our research?</h2><p>Get in touch about collaborations, student projects and research questions.</p></div><a class="button" href="mailto:mwpedersen@sund.ku.dk">Contact Mikkel</a></div></div>''')
talks = json.loads((r/'talks.json').read_text(encoding='utf-8'))
talk_rows = ''.join(f'<article class="paper"><span class="year">{escape(t["year"])}</span><div><h3>{escape(t["title"])}</h3><p>{escape(t["event"])}</p><p>{escape(t["type"])}</p><p><a href="{escape(t["url"], quote=True)}">{escape(t["link"])}</a></p></div></article>' for t in talks)
page('talks.html','Talks','Talks by Mikkel Winther Pedersen about ancient DNA, past ecosystems and the relationship between people and nature.',f'''<div class="wrap"><div class="page-intro"><p class="eyebrow">Researcher and speaker</p><h1>Stories from<br>the DNA of the past.</h1><p class="lead">How can a handful of soil reveal an entire lost ecosystem? I share the discoveries, fieldwork and scientific questions behind ancient environmental DNA.</p><div class="buttons"><a class="button" href="#enquiries">Enquire about a talk</a><a class="button secondary" href="#past-talks">Previous talks</a></div></div><figure class="speaker-photo"><img src="assets/mikkel-speaking-retouched.jpg" alt="Mikkel Winther Pedersen speaking to the audience at Arktisk Festival 2026" width="1672" height="941"><figcaption class="caption">Arktisk Festival 2026. Photo: Mads Lumholt.</figcaption></figure><section class="section"><div class="section-heading"><h2>Topics I speak about</h2><p>From public lectures to scientific conferences, my talks draw on research into past nature and the traces it leaves behind.</p></div><div class="research-grid"><article><h3>A lost Greenland</h3><p>The discovery of two-million-year-old DNA and the plants and animals that once lived in a much warmer Greenland.</p></article><article><h3>Nature’s genetic archive</h3><p>How DNA survives in soil and lake sediments, how we recover it, and what it can tell us about ecosystems that no longer exist.</p></article><article><h3>People, climate and biodiversity</h3><p>What ancient environmental DNA reveals about the relationship between human activity, changing climates and biodiversity through time.</p></article></div></section><section class="section past-talks" id="past-talks"><div class="section-heading"><h2>Selected previous talks</h2><p>Examples of public lectures, invited talks and conference keynotes.</p></div>{talk_rows}</section><section class="press-contact" id="enquiries"><h2>Enquire about a talk</h2><p>Write to me with a few words about your event, audience, preferred topic, date and location. We can discuss the format and practical arrangements.</p><div class="buttons"><a class="button" href="mailto:mwpedersen@sund.ku.dk?subject=Foredrag%20%2F%20Speaking%20enquiry">Contact me about a talk</a><a class="button secondary" href="press.html">Press materials and outreach</a></div></section></div>''')
outreach_items = json.loads((r/'outreach.json').read_text(encoding='utf-8'))
outreach_cards = ''.join(f'<article class="outreach-item"><p class="eyebrow">{escape(item["type"])}</p><h3>{escape(item["title"])}</h3><p>{escape(item["description"])}</p><p><a href="{escape(item["url"], quote=True)}">{escape(item["link"])}</a></p></article>' for item in outreach_items)
outreach_section = f'<section class="outreach-section" aria-labelledby="outreach-heading"><div class="section-heading"><div><p class="eyebrow">Science beyond academia</p><h2 id="outreach-heading">Selected public engagement</h2></div><p>Examples of documentaries, public talks, articles and conversations about my research.</p></div><div class="outreach-grid">{outreach_cards}</div></section>'
press_photos = json.loads((r/'press-photos.json').read_text(encoding='utf-8'))
photo_sections = ''
for group, heading in [('portraits', 'Press portraits'), ('events', 'Talks and teaching')]:
 photo_cards = ''
 for photo in (item for item in press_photos if item['group'] == group):
  credit = '<p class="note">Photo: '+escape(photo['credit'])+'</p>' if photo['credit'] else ''
  edit_note = '<p class="note">'+escape(photo['edit_note'])+'</p>' if photo.get('edit_note') else ''
  size = (r/photo['download']).stat().st_size / 1_000_000
  filetype = Path(photo['download']).suffix[1:].upper()
  photo_cards += f'<article class="press-photo-card"><a class="photo-preview" href="{photo["download"]}" aria-label="{escape(photo["title"], quote=True)}"><img src="{photo["image"]}" alt="{escape(photo["title"], quote=True)} — Mikkel Winther Pedersen" width="{photo["width"]}" height="{photo["height"]}" loading="lazy"></a><div class="press-photo-details"><h3>{escape(photo["title"])}</h3>{credit}{edit_note}<p class="note">{photo["width"]} × {photo["height"]} px · {size:.1f} MB</p><a class="button secondary" href="{photo["download"]}" download>Download · {filetype}</a></div></article>'
 photo_sections += f'<section class="press-photo-section" aria-labelledby="photos-{group}"><h2 id="photos-{group}">{heading}</h2><div class="press-photo-grid">{photo_cards}</div></section>'
photo_gallery = '<div class="press-photo-gallery"><p class="note">Download individual images in full resolution. Please include the photographer credit where shown. Contact Mikkel for questions about image use.</p>'+photo_sections+'</div>'
page('press.html','For journalists','Download a portrait, short biography and CV. Contact Mikkel Winther Pedersen for interviews about ancient DNA and past ecosystems.',f'''<div class="wrap"><div class="page-intro"><p class="eyebrow">Press & media</p><h1>For journalists</h1><p class="lead">Portraits, background information and contact details for coverage of ancient DNA, past ecosystems and environmental change.</p></div><div class="press-contact"><h2>Interviews & enquiries</h2><p><a href="mailto:mwpedersen@sund.ku.dk">mwpedersen@sund.ku.dk</a> · <a href="tel:+4529275342">+45 29 27 53 42</a></p><p>I welcome enquiries about ancient environmental DNA, biodiversity through time, Arctic ecosystems and the relationship between people and their environments.</p></div>{photo_gallery}<section class="press-background" aria-label="Press downloads"><article class="download-card"><p class="eyebrow">Background information</p><h2>Short biography</h2><div class="bio-text"><p>{bio}</p></div><div class="buttons"><a class="button secondary" href="downloads/Mikkel-Winther-Pedersen-short-biography.txt" download>Download biography · TXT</a><a class="button secondary" href="{cv}" download>Download CV · PDF</a></div><p class="note">CV updated November 2026</p></article></section>{outreach_section}</div>''')
